[CmdletBinding()]param([int]$Port=5080,[ValidateSet('Development','Production')][string]$Environment='Development')
$ErrorActionPreference='Stop';$workspace=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);$dotnet=Join-Path $workspace '.research\.dotnet\dotnet.exe';$runtime=Join-Path $PSScriptRoot '.runtime';New-Item -ItemType Directory -Force -Path $runtime|Out-Null;$pidPath=Join-Path $runtime 'surftimer-web.pid';if(Test-Path $pidPath){$old=[int](Get-Content $pidPath);if(Get-Process -Id $old -ErrorAction SilentlyContinue){throw "SurfTimer web is already running (PID $old)."}}
$project=Join-Path $workspace 'web\SurfTimer.Web.csproj';& $dotnet build $project -c Release --no-restore;if($LASTEXITCODE-ne 0){throw "SurfTimer web build failed with exit code $LASTEXITCODE."};$dll=Join-Path $workspace 'web\bin\Release\net10.0\SurfTimer.Web.dll';$dllArgument='"'+$dll+'"';$stdout=Join-Path $runtime 'surftimer-web.log';$stderr=Join-Path $runtime 'surftimer-web-error.log';$env:SURFTIMER_WEB_URL="http://127.0.0.1:$Port";$env:DOTNET_ENVIRONMENT=$Environment;$process=Start-Process -FilePath $dotnet -ArgumentList $dllArgument -WorkingDirectory (Join-Path $workspace 'web') -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;Set-Content -LiteralPath $pidPath -Value $process.Id;Start-Sleep -Seconds 2;if(-not(Get-Process -Id $process.Id -ErrorAction SilentlyContinue)){throw "SurfTimer web exited during startup. See $stderr"};Write-Host "SurfTimer web started (PID $($process.Id), $Environment): http://127.0.0.1:$Port";Write-Host "Logs: $stdout"
